#!/usr/bin/env bash
# Требует, чтобы тест транспорта на настоящем сокете именно прошёл.
#
# Зачем отдельно от общего прогона тестов. `tests/test_transport_ws.py` умеет
# пропуститься: библиотека транспорта — необязательный extra, и без неё
# `pytest.importorskip` превращает отсутствие в skip, а skip — в зелёный
# прогон. То есть исчезни `pymax` из окружения, и единственная проверка,
# которая вообще доходит до сокета, перестала бы что-либо проверять, никак этого
# не показав. Ровно так проверка состава публикуемого образа полтора месяца была
# зелёной, ничего не выполняя.
#
# Отсюда правило, ради которого скрипт и существует: проверка обязана
# предъявить доказательство работы. Здесь их три — ненулевой код возврата
# pytest, любое `skipped` в выводе и отсутствие хотя бы одного `passed` роняют
# шаг по отдельности.
#
# Код возврата сверяется явно, хотя шаг GitHub и так исполняется как `bash -e`,
# и падение подхватилось бы само. Полагаться на это не стоит: флага не видно в
# самом файле, а цена ошибки здесь — «упавший тест выглядит пройденным», потому
# что в выводе `5 passed, 1 failed` подстрока `passed` есть.
#
# Команда запуска приходит аргументами — тот же гейт нужен и на хосте, и внутри
# образа:
#   bash .github/scripts/transport-socket-gate.sh python -m pytest
#   bash .github/scripts/transport-socket-gate.sh docker run --rm ... image python -m pytest
set -euo pipefail

if [ "$#" -eq 0 ]; then
    echo "укажите команду запуска pytest, например: $0 python -m pytest" >&2
    exit 2
fi

target="tests/test_transport_ws.py"

status=0
output="$("$@" "$target" -q --color=no -p no:cacheprovider 2>&1)" || status=$?
printf '%s\n' "$output"

if [ "$status" != "0" ]; then
    echo "тест транспорта на сокете не прошёл, код возврата $status" >&2
    exit 1
fi

case "$output" in
    *skipped*)
        echo "тест транспорта на сокете пропущен: проверять было нечем" >&2
        exit 1
        ;;
esac

if ! printf '%s' "$output" | grep -Eq '[0-9]+ passed'; then
    echo "в выводе нет ни одного пройденного теста" >&2
    exit 1
fi

echo "транспорт проверен на настоящем сокете"
